package com.lmspilot.identity.config;
import com.lmspilot.identity.domain.*; import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class DevelopmentSeed implements ApplicationRunner {
 private final RoleRepository roles; private final UserAccountRepository users; private final PasswordEncoder encoder; private final boolean enabled; private final String password;
 public DevelopmentSeed(RoleRepository r,UserAccountRepository u,PasswordEncoder e,@Value("${lmspilot.seed-demo:false}") boolean enabled,@Value("${lmspilot.default-admin-password:ChangeMe!12345}") String password){roles=r;users=u;encoder=e;this.enabled=enabled;this.password=password;}
 @Override @Transactional public void run(ApplicationArguments args){if(!enabled)return;ensure("00000000-0000-0000-0000-000000000001","ADM001","admin","Quản trị hệ thống","ADMIN",true);ensure("00000000-0000-0000-0000-000000000002","INS001","instructor","Giảng viên mẫu","INSTRUCTOR",false);ensure("00000000-0000-0000-0000-000000000003","STU001","student","Học viên mẫu","STUDENT",false);}
 private void ensure(String id,String code,String username,String name,String role,boolean protect){UUID demoId=UUID.fromString(id);Optional<UserAccountEntity> existing=users.findByUsernameIgnoreCase(username);if(existing.isPresent()){UserAccountEntity u=existing.get();if(!demoId.equals(u.id))return;u.passwordHash=encoder.encode(password);u.failedLoginCount=0;u.lockedUntil=null;u.status=AccountStatus.ACTIVE;u.mustChangePassword=false;u.passwordChangedAt=Instant.now();u.updatedAt=Instant.now();users.save(u);return;}RoleEntity r=roles.findByCodeIgnoreCase(role).orElseThrow();UserAccountEntity u=new UserAccountEntity();u.id=demoId;u.code=code;u.username=username;u.fullName=name;u.passwordHash=encoder.encode(password);u.roles=new LinkedHashSet<>(Set.of(r));u.accountType=protect?AccountType.SYSTEM_ADMIN:AccountType.USER;u.protectedAccount=protect;u.mustChangePassword=false;u.passwordChangedAt=Instant.now();users.save(u);}
}
